const upsertCurrentMediaAuthority = `-- name: UpsertCurrentMediaAuthority :execrows
INSERT INTO commodore.media_authority_current (
    authority_kind, authority_id, authority_version, updated_at
) VALUES (
    $1, $2, $3, NOW()
)
ON CONFLICT (authority_kind, authority_id) DO UPDATE
SET authority_version = EXCLUDED.authority_version,
    updated_at = NOW()
WHERE commodore.media_authority_current.authority_version < EXCLUDED.authority_version
`

type UpsertCurrentMediaAuthorityParams struct {
	AuthorityKind    string `db:"authority_kind" json:"authority_kind"`
	AuthorityID      string `db:"authority_id" json:"authority_id"`
	AuthorityVersion int64  `db:"authority_version" json:"authority_version"`
}

func (q *Queries) UpsertCurrentMediaAuthority(ctx context.Context, arg UpsertCurrentMediaAuthorityParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, upsertCurrentMediaAuthority, arg.AuthorityKind, arg.AuthorityID, arg.AuthorityVersion)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const upsertMediaAuthorityDistribution = `-- name: UpsertMediaAuthorityDistribution :exec
INSERT INTO commodore.media_authority_distribution (
    authority_kind, authority_id, cell_id, highest_acknowledged_version,
    first_acknowledged_at, last_acknowledged_at
) VALUES (
    $1, $2, $3,
    $4, NOW(), NOW()
)
ON CONFLICT (authority_kind, authority_id, cell_id) DO UPDATE
SET highest_acknowledged_version = GREATEST(
        commodore.media_authority_distribution.highest_acknowledged_version,
        EXCLUDED.highest_acknowledged_version
    ),
    last_acknowledged_at = NOW()
`

type UpsertMediaAuthorityDistributionParams struct {
	AuthorityKind    string `db:"authority_kind" json:"authority_kind"`
	AuthorityID      string `db:"authority_id" json:"authority_id"`
	CellID           string `db:"cell_id" json:"cell_id"`
	AuthorityVersion int64  `db:"authority_version" json:"authority_version"`
}

func (q *Queries) UpsertMediaAuthorityDistribution(ctx context.Context, arg UpsertMediaAuthorityDistributionParams) error {
	_, err := q.db.ExecContext(ctx, upsertMediaAuthorityDistribution,
		arg.AuthorityKind,
		arg.AuthorityID,
		arg.CellID,
		arg.AuthorityVersion,
	)
	return err
}

